343. export async function withdrawStake(
344.   connection: Connection,
345.   stakePoolAddress: PublicKey,
346.   tokenOwner: PublicKey,
347.   amount: number,
348.   useReserve = false,
349.   voteAccountAddress?: PublicKey,
350.   stakeReceiver?: PublicKey,
351.   poolTokenAccount?: PublicKey,
352.   validatorComparator?: (_a: ValidatorAccount, _b: ValidatorAccount) => number,
353. ) {
354.   const stakePool = await getStakePoolAccount(connection, stakePoolAddress);
355.   const poolAmount = solToLamports(amount);
356. 
357.   if (!poolTokenAccount) {
358.     poolTokenAccount = await Token.getAssociatedTokenAddress(
359.       ASSOCIATED_TOKEN_PROGRAM_ID,
360.       TOKEN_PROGRAM_ID,
361.       stakePool.account.data.poolMint,
362.       tokenOwner,
363.     );
364.   }
365. 
366.   const tokenAccount = await getTokenAccount(
367.     connection,
368.     poolTokenAccount,
369.     stakePool.account.data.poolMint,
370.   );
371. 
372.   if (!tokenAccount) {
373.     throw new Error('Invalid token account');
374.   }
375. 
376.   // Check withdrawFrom balance
377.   if (tokenAccount.amount.toNumber() < poolAmount) {
378.     throw new Error(
379.       `Not enough token balance to withdraw ${lamportsToSol(poolAmount)} pool tokens.
380.         Maximum withdraw amount is ${lamportsToSol(tokenAccount.amount.toNumber())} pool tokens.`,
381.     );
382.   }
383. 
384.   const stakeAccountRentExemption = await connection.getMinimumBalanceForRentExemption(
385.     StakeProgram.space,
386.   );
387. 
388.   const withdrawAuthority = await findWithdrawAuthorityProgramAddress(
389.     STAKE_POOL_PROGRAM_ID,
390.     stakePoolAddress,
391.   );
392. 
393.   let stakeReceiverAccount = null;
394.   if (stakeReceiver) {
395.     stakeReceiverAccount = await getStakeAccount(connection, stakeReceiver);
396.   }
397. 
398.   const withdrawAccounts: WithdrawAccount[] = [];
399. 
400.   if (useReserve) {
401.     withdrawAccounts.push({
402.       stakeAddress: stakePool.account.data.reserveStake,
403.       voteAddress: undefined,
404.       poolAmount,
405.     });
406.   } else if (stakeReceiverAccount && stakeReceiverAccount?.type == 'delegated') {
407.     const voteAccount = stakeReceiverAccount.info?.stake?.delegation.voter;
408.     if (!voteAccount) throw new Error(`Invalid stake reciever ${stakeReceiver} delegation`);
409.     const validatorListAccount = await connection.getAccountInfo(
410.       stakePool.account.data.validatorList,
411.     );
412.     const validatorList = ValidatorListLayout.decode(validatorListAccount?.data) as ValidatorList;
413.     const isValidVoter = validatorList.validators.find((val) =>
414.       val.voteAccountAddress.equals(voteAccount),
415.     );
416.     if (voteAccountAddress && voteAccountAddress !== voteAccount) {
417.       throw new Error(`Provided withdrawal vote account ${voteAccountAddress} does not match delegation on stake receiver account ${voteAccount},
418.       remove this flag or provide a different stake account delegated to ${voteAccountAddress}`);
419.     }
420.     if (isValidVoter) {
421.       const stakeAccountAddress = await findStakeProgramAddress(
422.         STAKE_POOL_PROGRAM_ID,
423.         voteAccount,
424.         stakePoolAddress,
425.       );
426. 
427.       const stakeAccount = await connection.getAccountInfo(stakeAccountAddress);
428.       if (!stakeAccount) {
429.         throw new Error(`Preferred withdraw valdator's stake account is invalid`);
430.       }
431. 
432.       const availableForWithdrawal = calcLamportsWithdrawAmount(
433.         stakePool.account.data,
434.         stakeAccount.lamports - MINIMUM_ACTIVE_STAKE - stakeAccountRentExemption,
435.       );
436. 
437.       if (availableForWithdrawal < poolAmount) {
438.         throw new Error(
439.           `Not enough lamports available for withdrawal from ${stakeAccountAddress},
440.             ${poolAmount} asked, ${availableForWithdrawal} available.`,
441.         );
442.       }
443.       withdrawAccounts.push({
444.         stakeAddress: stakeAccountAddress,
445.         voteAddress: voteAccount,
446.         poolAmount,
447.       });
448.     } else {
449.       throw new Error(
450.         `Provided stake account is delegated to a vote account ${voteAccount} which does not exist in the stake pool`,
451.       );
452.     }
453.   } else if (voteAccountAddress) {
454.     const stakeAccountAddress = await findStakeProgramAddress(
455.       STAKE_POOL_PROGRAM_ID,
456.       voteAccountAddress,
457.       stakePoolAddress,
458.     );
459.     const stakeAccount = await connection.getAccountInfo(stakeAccountAddress);
460.     if (!stakeAccount) {
461.       throw new Error('Invalid Stake Account');
462.     }
463. 
464.     const availableForWithdrawal = calcLamportsWithdrawAmount(
465.       stakePool.account.data,
466.       stakeAccount.lamports - MINIMUM_ACTIVE_STAKE - stakeAccountRentExemption,
467.     );
468. 
469.     if (availableForWithdrawal < poolAmount) {
470.       // noinspection ExceptionCaughtLocallyJS
471.       throw new Error(
472.         `Not enough lamports available for withdrawal from ${stakeAccountAddress},
473.           ${poolAmount} asked, ${availableForWithdrawal} available.`,
474.       );
475.     }
476.     withdrawAccounts.push({
477.       stakeAddress: stakeAccountAddress,
478.       voteAddress: voteAccountAddress,
479.       poolAmount,
480.     });
481.   } else {
482.     // Get the list of accounts to withdraw from
483.     withdrawAccounts.push(
484.       ...(await prepareWithdrawAccounts(
485.         connection,
486.         stakePool.account.data,
487.         stakePoolAddress,
488.         poolAmount,
489.         validatorComparator,
490.         poolTokenAccount.equals(stakePool.account.data.managerFeeAccount),
491.       )),
492.     );
493.   }
494. 
495.   // Construct transaction to withdraw from withdrawAccounts account list
496.   const instructions: TransactionInstruction[] = [];
497.   const userTransferAuthority = Keypair.generate();
498. 
499.   const signers: Signer[] = [userTransferAuthority];
500. 
501.   instructions.push(
502.     Token.createApproveInstruction(
503.       TOKEN_PROGRAM_ID,
504.       poolTokenAccount,
505.       userTransferAuthority.publicKey,
506.       tokenOwner,
507.       [],
508.       poolAmount,
509.     ),
510.   );
511. 
512.   let totalRentFreeBalances = 0;
513. 
514.   // Max 5 accounts to prevent an error: "Transaction too large"
515.   const maxWithdrawAccounts = 5;
516.   let i = 0;
517. 
518.   // Go through prepared accounts and withdraw/claim them
519.   for (const withdrawAccount of withdrawAccounts) {
520.     if (i > maxWithdrawAccounts) {
521.       break;
522.     }
523.     // Convert pool tokens amount to lamports
524.     const solWithdrawAmount = Math.ceil(
525.       calcLamportsWithdrawAmount(stakePool.account.data, withdrawAccount.poolAmount),
526.     );
527. 
528.     let infoMsg = `Withdrawing ◎${solWithdrawAmount},
529.       from stake account ${withdrawAccount.stakeAddress?.toBase58()}`;
530. 
531.     if (withdrawAccount.voteAddress) {
532.       infoMsg = `${infoMsg}, delegated to ${withdrawAccount.voteAddress?.toBase58()}`;
533.     }
534. 
535.     console.info(infoMsg);
536.     let stakeToReceive;
537. 
538.     if (!stakeReceiver || (stakeReceiverAccount && stakeReceiverAccount.type === 'delegated')) {
539.       const stakeKeypair = newStakeAccount(tokenOwner, instructions, stakeAccountRentExemption);
540.       signers.push(stakeKeypair);
541.       totalRentFreeBalances += stakeAccountRentExemption;
542.       stakeToReceive = stakeKeypair.publicKey;
543.     } else {
544.       stakeToReceive = stakeReceiver;
545.     }
546. 
547.     instructions.push(
548.       StakePoolInstruction.withdrawStake({
549.         stakePool: stakePoolAddress,
550.         validatorList: stakePool.account.data.validatorList,
551.         validatorStake: withdrawAccount.stakeAddress,
552.         destinationStake: stakeToReceive,
553.         destinationStakeAuthority: tokenOwner,
554.         sourceTransferAuthority: userTransferAuthority.publicKey,
555.         sourcePoolAccount: poolTokenAccount,
556.         managerFeeAccount: stakePool.account.data.managerFeeAccount,
557.         poolMint: stakePool.account.data.poolMint,
558.         poolTokens: withdrawAccount.poolAmount,
559.         withdrawAuthority,
560.       }),
561.     );
562.     i++;
563.   }
564.   if (stakeReceiver && stakeReceiverAccount && stakeReceiverAccount.type === 'delegated') {
565.     signers.forEach((newStakeKeypair) => {
566.       instructions.concat(
567.         StakeProgram.merge({
568.           stakePubkey: stakeReceiver,
569.           sourceStakePubKey: newStakeKeypair.publicKey,
570.           authorizedPubkey: tokenOwner,
571.         }).instructions,
572.       );
573.     });
574.   }
575. 
576.   return {
577.     instructions,
578.     signers,
579.     stakeReceiver,
580.     totalRentFreeBalances,
581.   };
582. }
