     if (tokenAccount.mint?.toBase58() != expectedTokenMint.toBase58()) {
       // noinspection ExceptionCaughtLocallyJS
       throw new Error(
         `Invalid token mint for ${tokenAccountAddress}, expected mint is ${expectedTokenMint}`,
       );
     }
     return tokenAccount;
   } catch (error) {
     console.log(error);
   }
 }

