15.   connection: Connection,
16.   tokenMintPubkey: PublicKey,
17. ): Promise<MintInfo | undefined> {
18.   // @ts-ignore
19.   const token = new Token(connection, tokenMintPubkey, TOKEN_PROGRAM_ID, null);
20.   return token.getMintInfo();
21. }
