23. /**
24.  * Retrieve the associated account or create one if not found.
25.  * This account may then be used as a `transfer()` or `approve()` destination
26.  */
27. export async function addAssociatedTokenAccount(
28.   connection: Connection,
29.   owner: PublicKey,
30.   mint: PublicKey,
31.   instructions: TransactionInstruction[],
32. ) {
33.   const associatedAddress = await Token.getAssociatedTokenAddress(
34.     ASSOCIATED_TOKEN_PROGRAM_ID,
35.     TOKEN_PROGRAM_ID,
36.     mint,
37.     owner,
38.   );
39. 
40.   let rentFee = 0;
41. 
42.   // This is the optimum logic, considering TX fee, client-side computation,
43.   // RPC roundtrips and guaranteed idempotent.
44.   // Sadly we can't do this atomically;
45.   try {
46.     const account = await connection.getAccountInfo(associatedAddress);
47.     if (!account) {
48.       // noinspection ExceptionCaughtLocallyJS
49.       throw new Error(FAILED_TO_FIND_ACCOUNT);
50.     }
51.   } catch (err: any) {
52.     // INVALID_ACCOUNT_OWNER can be possible if the associatedAddress has
53.     // already been received some lamports (= became system accounts).
