1. import { struct, u32, u8 } from '@solana/buffer-layout';
2. import { bool, publicKey, u64 } from '@solana/buffer-layout-utils';
3. import type { AccountInfo, Commitment, Connection } from '@solana/web3.js';
4. import { PublicKey } from '@solana/web3.js';
5. import { ASSOCIATED_TOKEN_PROGRAM_ID, TOKEN_PROGRAM_ID } from '../constants.js';
6. import {
7.     TokenAccountNotFoundError,
8.     TokenInvalidAccountOwnerError,
9.     TokenInvalidAccountSizeError,
10.     TokenInvalidMintError,
11.     TokenOwnerOffCurveError,
12. } from '../errors.js';
13. import { ACCOUNT_TYPE_SIZE, AccountType } from '../extensions/accountType.js';
14. import type { ExtensionType } from '../extensions/extensionType.js';
15. import { getMintLen } from '../extensions/extensionType.js';
16. import { ACCOUNT_SIZE } from './account.js';
17. import { MULTISIG_SIZE } from './multisig.js';
18. 
19. /** Information about a mint */
20. export interface Mint {
21.     /** Address of the mint */
22.     address: PublicKey;
23.     /**
24.      * Optional authority used to mint new tokens. The mint authority may only be provided during mint creation.
25.      * If no mint authority is present then the mint has a fixed supply and no further tokens may be minted.
26.      */
27.     mintAuthority: PublicKey | null;
28.     /** Total supply of tokens */
29.     supply: bigint;
30.     /** Number of base 10 digits to the right of the decimal place */
31.     decimals: number;
32.     /** Is this mint initialized */
33.     isInitialized: boolean;
34.     /** Optional authority to freeze token accounts */
35.     freezeAuthority: PublicKey | null;
36.     /** Additional data for extension */
37.     tlvData: Buffer;
38. }
39. 
40. /** Mint as stored by the program */
41. export interface RawMint {
42.     mintAuthorityOption: 1 | 0;
43.     mintAuthority: PublicKey;
44.     supply: bigint;
45.     decimals: number;
46.     isInitialized: boolean;
47.     freezeAuthorityOption: 1 | 0;
48.     freezeAuthority: PublicKey;
49. }
50. 
51. /** Buffer layout for de/serializing a mint */
52. export const MintLayout = struct<RawMint>([
53.     u32('mintAuthorityOption'),
54.     publicKey('mintAuthority'),
55.     u64('supply'),
56.     u8('decimals'),
57.     bool('isInitialized'),
58.     u32('freezeAuthorityOption'),
59.     publicKey('freezeAuthority'),
60. ]);
61. 
62. /** Byte length of a mint */
63. export const MINT_SIZE = MintLayout.span;
64. 
65. /**
66.  * Retrieve information about a mint
67.  *
68.  * @param connection Connection to use
69.  * @param address    Mint account
70.  * @param commitment Desired level of commitment for querying the state
71.  * @param programId  SPL Token program account
72.  *
73.  * @return Mint information
74.  */
75. export async function getMint(
76.     connection: Connection,
77.     address: PublicKey,
78.     commitment?: Commitment,
79.     programId = TOKEN_PROGRAM_ID
80. ): Promise<Mint> {
81.     const info = await connection.getAccountInfo(address, commitment);
82.     return unpackMint(address, info, programId);
83. }
84. 
85. /**
86.  * Unpack a mint
87.  *
88.  * @param address   Mint account
89.  * @param info      Mint account data
90.  * @param programId SPL Token program account
91.  *
92.  * @return Unpacked mint
93.  */
94. export function unpackMint(address: PublicKey, info: AccountInfo<Buffer> | null, programId = TOKEN_PROGRAM_ID): Mint {
95.     if (!info) throw new TokenAccountNotFoundError();
96.     if (!info.owner.equals(programId)) throw new TokenInvalidAccountOwnerError();
97.     if (info.data.length < MINT_SIZE) throw new TokenInvalidAccountSizeError();
98. 
99.     const rawMint = MintLayout.decode(info.data.slice(0, MINT_SIZE));
100.     let tlvData = Buffer.alloc(0);
101.     if (info.data.length > MINT_SIZE) {
102.         if (info.data.length <= ACCOUNT_SIZE) throw new TokenInvalidAccountSizeError();
103.         if (info.data.length === MULTISIG_SIZE) throw new TokenInvalidAccountSizeError();
104.         if (info.data[ACCOUNT_SIZE] != AccountType.Mint) throw new TokenInvalidMintError();
105.         tlvData = info.data.slice(ACCOUNT_SIZE + ACCOUNT_TYPE_SIZE);
106.     }
107. 
108.     return {
109.         address,
110.         mintAuthority: rawMint.mintAuthorityOption ? rawMint.mintAuthority : null,
111.         supply: rawMint.supply,
112.         decimals: rawMint.decimals,
113.         isInitialized: rawMint.isInitialized,
114.         freezeAuthority: rawMint.freezeAuthorityOption ? rawMint.freezeAuthority : null,
115.         tlvData,
116.     };
117. }
118. 
119. /** Get the minimum lamport balance for a mint to be rent exempt
120.  *
121.  * @param connection Connection to use
122.  * @param commitment Desired level of commitment for querying the state
123.  *
124.  * @return Amount of lamports required
125.  */
126. export async function getMinimumBalanceForRentExemptMint(
127.     connection: Connection,
128.     commitment?: Commitment
129. ): Promise<number> {
130.     return await getMinimumBalanceForRentExemptMintWithExtensions(connection, [], commitment);
131. }
132. 
133. /** Get the minimum lamport balance for a rent-exempt mint with extensions
134.  *
135.  * @param connection Connection to use
136.  * @param extensions Extension types included in the mint
137.  * @param commitment Desired level of commitment for querying the state
138.  *
139.  * @return Amount of lamports required
140.  */
141. export async function getMinimumBalanceForRentExemptMintWithExtensions(
142.     connection: Connection,
143.     extensions: ExtensionType[],
144.     commitment?: Commitment
145. ): Promise<number> {
146.     const mintLen = getMintLen(extensions);
147.     return await connection.getMinimumBalanceForRentExemption(mintLen, commitment);
148. }
149. 
150. /**
151.  * Async version of getAssociatedTokenAddressSync
152.  * For backwards compatibility
153.  *
154.  * @param mint                     Token mint account
155.  * @param owner                    Owner of the new account
156.  * @param allowOwnerOffCurve       Allow the owner account to be a PDA (Program Derived Address)
157.  * @param programId                SPL Token program account
158.  * @param associatedTokenProgramId SPL Associated Token program account
159.  *
160.  * @return Promise containing the address of the associated token account
161.  */
162. export async function getAssociatedTokenAddress(
163.     mint: PublicKey,
164.     owner: PublicKey,
165.     allowOwnerOffCurve = false,
166.     programId = TOKEN_PROGRAM_ID,
167.     associatedTokenProgramId = ASSOCIATED_TOKEN_PROGRAM_ID
168. ): Promise<PublicKey> {
169.     if (!allowOwnerOffCurve && !PublicKey.isOnCurve(owner.toBuffer())) throw new TokenOwnerOffCurveError();
170. 
171.     const [address] = await PublicKey.findProgramAddress(
172.         [owner.toBuffer(), programId.toBuffer(), mint.toBuffer()],
173.         associatedTokenProgramId
174.     );
175. 
176.     return address;
177. }
178. 
179. /**
180.  * Get the address of the associated token account for a given mint and owner
181.  *
182.  * @param mint                     Token mint account
183.  * @param owner                    Owner of the new account
184.  * @param allowOwnerOffCurve       Allow the owner account to be a PDA (Program Derived Address)
185.  * @param programId                SPL Token program account
186.  * @param associatedTokenProgramId SPL Associated Token program account
187.  *
188.  * @return Address of the associated token account
189.  */
190. export function getAssociatedTokenAddressSync(
191.     mint: PublicKey,
192.     owner: PublicKey,
193.     allowOwnerOffCurve = false,
194.     programId = TOKEN_PROGRAM_ID,
195.     associatedTokenProgramId = ASSOCIATED_TOKEN_PROGRAM_ID
196. ): PublicKey {
197.     if (!allowOwnerOffCurve && !PublicKey.isOnCurve(owner.toBuffer())) throw new TokenOwnerOffCurveError();
198. 
199.     const [address] = PublicKey.findProgramAddressSync(
200.         [owner.toBuffer(), programId.toBuffer(), mint.toBuffer()],
201.         associatedTokenProgramId
202.     );
203. 
204.     return address;
205. }
206.

